BEGIN;

CREATE TABLE IF NOT EXISTS public.password_reset_tokens
(
    "Id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,

    "UsuarioId" INTEGER NOT NULL,

    "TokenHash" VARCHAR(128) NOT NULL,

    "FechaCreacion" TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    "FechaExpiracion" TIMESTAMPTZ NOT NULL,

    "FechaUso" TIMESTAMPTZ NULL,

    CONSTRAINT "PK_password_reset_tokens"
        PRIMARY KEY ("Id"),

    CONSTRAINT "FK_password_reset_tokens_usuarios"
        FOREIGN KEY ("UsuarioId")
        REFERENCES public.usuarios ("Id")
        ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS
    "IX_password_reset_tokens_UsuarioId"
ON public.password_reset_tokens ("UsuarioId");

CREATE INDEX IF NOT EXISTS
    "IX_password_reset_tokens_TokenHash"
ON public.password_reset_tokens ("TokenHash");

CREATE INDEX IF NOT EXISTS
    "IX_password_reset_tokens_FechaExpiracion"
ON public.password_reset_tokens ("FechaExpiracion");

COMMIT;